    source_def = def_host[rows, owner_safe, src_safe]
    source_stt01_002 = (
        (source_def == self._stt01_002_id)
        & np.asarray(states.ab_costs_applied)
        & (np.asarray(states.ab_scratch)[:, 2] == 2)
    )
